        if dx != 0 and dy != 0:
            if abs(target_x - x) >= abs(target_y - y):
                dy = 0
            else:
                dx = 0
        return [dx, dy]

    # 3) Generic exploration: move toward center-ish if no targets
    center_dx = 0
